// Turns the owner's Lottie launch animation into plain files, so the splash plays from the very first paint with no Lottie player
// (about 250 KB of JavaScript saved). The file has image layers only (the "g" and the "ebzem" lettering) animated by position,
// scale and opacity, plus one rectangular left-to-right reveal mask; anything else is rejected rather than drawn wrongly.
// Writes public/brand/splash/<asset>.webp and src/components/pwa/app-splash.css (generated; do not edit by hand).
// Usage: node scripts/dev/splash-from-lottie.mjs <lottie.json>
// Keep the Lottie file itself out of the repo and never print it: it carries ~230 KB of base64 images on one line.
import fs from "node:fs";
import sharp from "sharp";

const src = process.argv[2];
if (!src) {
  console.error("usage: node scripts/dev/splash-from-lottie.mjs <lottie.json>");
  process.exit(1);
}
const lottie = JSON.parse(fs.readFileSync(src, "utf8"));
const { w: W, fr, ip, op } = lottie; // square canvas: every size is a share of its width
const FRAMES = op - ip;
const SECONDS = FRAMES / fr;
const STEP = 2; // a keyframe every 2 frames (30 per second); the browser interpolates linearly in between
const STAGE_MAX_PX = 430; // the stage is min(100vw, 430px) square
const DPR = 3;
const IMG_DIR = "public/brand/splash";
const CSS_FILE = "src/components/pwa/app-splash.css";

const fail = (msg) => {
  console.error(msg);
  process.exit(1);
};
const lerp = (a, b, f) => a + (b - a) * f;
if (lottie.w !== lottie.h) fail("the canvas must be square (the stage is a square box)");

/** Value of an animated property at frame t (baked linear keyframes, "s"/"e" or consecutive "s"). */
function at(prop, t) {
  if (!prop.a) return prop.k;
  const keys = prop.k;
  let i = 0;
  while (i + 1 < keys.length && keys[i + 1].t <= t) i++;
  const cur = keys[i];
  const next = keys[i + 1];
  const end = cur.e ?? next?.s;
  if (!next || !end || cur.h) return cur.s;
  const f = Math.min(1, Math.max(0, (t - cur.t) / (next.t - cur.t)));
  if (typeof cur.s[0] === "object") {
    // Mask path: interpolate every vertex.
    return [{ ...cur.s[0], v: cur.s[0].v.map((p, j) => [lerp(p[0], end[0].v[j][0], f), lerp(p[1], end[0].v[j][1], f)]) }];
  }
  return cur.s.map((v, j) => lerp(v, end[j], f));
}
const num = (x) => (Array.isArray(x) ? x : [x]);
const round = (x, d = 3) => String(Number(x.toFixed(d)));
const pct = (x) => `${round(x)}%`;

const assets = new Map(lottie.assets.map((a) => [a.id, a]));
let css = `/* Generated by scripts/dev/splash-from-lottie.mjs from the Lottie file "${lottie.nm}" (${round(SECONDS, 2)} s, ${fr} fps). Do not edit by hand. */
.gz-splash-stage{position:relative;width:min(100vw,${STAGE_MAX_PX}px);aspect-ratio:1;flex:none}
.gz-splash-stage>img{position:absolute;left:0;top:0;height:auto;max-width:none;transform-origin:0 0;animation-duration:${round(SECONDS, 3)}s;animation-timing-function:linear;animation-fill-mode:both}
`;
fs.mkdirSync(IMG_DIR, { recursive: true });

for (const layer of lottie.layers) {
  if (layer.ty !== 2) fail(`layer "${layer.nm}" is not an image layer`);
  if (layer.parent || layer.tt || layer.ks.r.a || layer.ks.r.k) fail(`layer "${layer.nm}" uses parenting, track mattes or rotation`);
  const asset = assets.get(layer.refId);
  const name = asset.id.replace(/^image_/, "");
  const masks = layer.masksProperties ?? [];
  if (masks.length > 1 || masks.some((m) => m.mode !== "a" || m.inv || m.x.a || m.x.k || m.o.a || m.o.k !== 100)) fail(`layer "${layer.nm}" has an unsupported mask`);

  // Image file, sized for its largest on-screen size at 3x.
  const maxScale = Math.max(...Array.from({ length: FRAMES + 1 }, (_, t) => num(at(layer.ks.s, t))[0] / 100));
  const outW = Math.ceil((asset.w * maxScale * (STAGE_MAX_PX / W) * DPR) / 8) * 8;
  const png = Buffer.from(String(asset.p).split(",")[1], "base64");
  const info = await sharp(png).resize({ width: outW }).webp({ lossless: true, effort: 6 }).toFile(`${IMG_DIR}/${name}.webp`);

  // One declaration block per sampled frame; runs of the same value keep only their two ends.
  const blocks = [];
  for (let t = 0; t <= FRAMES; t = t === FRAMES ? t + 1 : Math.min(FRAMES, t + STEP)) {
    const [ax, ay] = num(at(layer.ks.a, t));
    const [px, py] = num(at(layer.ks.p, t));
    const [sx, sy] = num(at(layer.ks.s, t)).map((v) => v / 100);
    const decls = [`transform:translate(${pct(((px - ax * sx) / asset.w) * 100)},${pct(((py - ay * sy) / asset.h) * 100)}) scale(${round(sx, 4)}${sx === sy ? "" : `,${round(sy, 4)}`})`];
    if (layer.ks.o.a || num(layer.ks.o.k)[0] !== 100) decls.push(`opacity:${round(num(at(layer.ks.o, t))[0] / 100, 3)}`);
    if (masks.length) {
      const v = at(masks[0].pt, t)[0].v;
      const xs = v.map((p) => p[0]);
      const ys = v.map((p) => p[1]);
      const clamp = (x) => Math.min(100, Math.max(0, x));
      const inset = [Math.min(...ys) / asset.h, (asset.w - Math.max(...xs)) / asset.w, (asset.h - Math.max(...ys)) / asset.h, Math.min(...xs) / asset.w];
      decls.push(`clip-path:inset(${inset.map((x) => pct(clamp(x * 100))).join(" ")})`);
    }
    blocks.push({ at: (t / FRAMES) * 100, body: decls.join(";") });
  }
  const kept = blocks.filter((b, i) => i === 0 || i === blocks.length - 1 || b.body !== blocks[i - 1].body || b.body !== blocks[i + 1].body);
  css += `.gz-splash-${name}{width:${pct((asset.w / W) * 100)};animation-name:gz-splash-${name}}\n`;
  css += `@keyframes gz-splash-${name}{${kept.map((b) => `${round(b.at)}%{${b.body}}`).join("")}}\n`;
  console.log(`${name}: ${IMG_DIR}/${name}.webp ${info.width}x${info.height} ${info.size} B, ${kept.length} keyframes`);
}

fs.writeFileSync(CSS_FILE, css);
console.log(`${CSS_FILE}: ${css.length} B, ${round(SECONDS, 3)} s`);
